package com.dorm.fourchess;

import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import org.json.*;import java.util.*;import java.lang.reflect.*;import java.io.*;

/** Real private-file persistence, progression, actual board settlement/undo and phone UI. */
public final class CareerProbe extends Instrumentation {
    private final StringBuilder log=new StringBuilder();private MainActivity activity;private Bundle args;
    @Override public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
    private void check(boolean b,String label){if(!b)throw new AssertionError(label);log.append("PASS ").append(label).append('\n');}
    private Object field(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
    private void set(Object o,String name,Object v)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,v);}
    private void invoke(Object o,String name)throws Exception{Method m=o.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(o);}
    private void main(Runnable r){java.util.concurrent.atomic.AtomicReference<Throwable> fail=new java.util.concurrent.atomic.AtomicReference<>();runOnMainSync(()->{try{r.run();}catch(Throwable e){fail.set(e);}});waitForIdleSync();if(fail.get()!=null)throw new AssertionError(fail.get());}
    private interface Ready{boolean yes()throws Exception;}
    private void await(Ready r,String text)throws Exception{for(int i=0;i<120;i++){if(r.yes()){check(true,text);return;}SystemClock.sleep(50);}throw new AssertionError(text);}
    private JSONObject match(String id,String player,String friend,boolean win,int side,long ended)throws Exception{JSONObject m=new JSONObject();m.put("id",id);m.put("mode","classic");m.put("started",ended-120000);m.put("ended",ended);m.put("side",side);m.put("result",win?"win":"loss");m.put("captures",2);m.put("skills",1);m.put("players",new JSONArray(Arrays.asList(player,friend,"","")));return m;}
    private void data()throws Exception{
        PlayerArchive s=new PlayerArchive(getTargetContext());JSONObject a=s.create("测试棋士甲",false),b=s.create("测试棋士乙",false),guest=s.create("临时游客",true);String aid=a.getString("id"),bid=b.getString("id");s.edit(aid,"月下棋友","持子问道",2);check(s.read(aid).getJSONObject("profile").getString("nickname").equals("月下棋友"),"nickname persisted to real atomic JSON");check(s.read(bid).getJSONObject("profile").getString("nickname").equals("测试棋士乙"),"independent account files never mix");
        s.addFriend(aid,PlayerArchive.card(b));s.addFriend(bid,PlayerArchive.card(a));s.note(aid,bid,"知音");check(s.read(aid).getJSONObject("friends").getJSONObject(bid).getString("note").equals("知音"),"friend card and remark persist");long now=System.currentTimeMillis()+2000;String first=UUID.randomUUID().toString();JSONObject record=match(first,aid,bid,true,0,now);check(s.settle(aid,record),"first unique match accepted");JSONObject won=s.read(aid);long xp=won.getLong("xp");check(!s.settle(aid,record)&&s.read(aid).getLong("xp")==xp,"duplicate match never increases XP or rewards");check(won.getJSONObject("friendStats").getJSONObject(bid).getInt("intimacy")==30,"first common match grants ten plus first twenty");check(won.getJSONObject("statistics").getInt("captures")==2&&won.getJSONObject("statistics").getInt("skills")==1,"real per-match capture and skill counts aggregated");check(!s.settle(guest.getString("id"),record)&&s.read(guest.getString("id")).getJSONObject("matches").length()==0,"temporary guest excluded from formal statistics");
        JSONObject remote=CareerRules.copy(won),local=CareerRules.copy(won);String second=UUID.randomUUID().toString();local.getJSONObject("matches").put(second,match(second,aid,bid,false,1,now+1000));remote.put("cloudRevision",2);JSONObject merged=PlayerArchive.merge(local,remote,true);check(merged.getJSONObject("matches").length()==2&&merged.optLong("cloudRevision")==2,"CAS conflict merges disjoint game IDs without losing remote revision");remote.put("id",bid);boolean rejected=false;try{PlayerArchive.merge(local,remote,true);}catch(Exception e){rejected=true;}check(rejected,"cross-account merge rejected");
        s.retract(aid,first);check(s.read(aid).getJSONObject("matches").length()==0,"undo retract removes match from growth");JSONObject stale=CareerRules.copy(won);JSONObject restored=PlayerArchive.merge(s.read(aid),stale,true);check(restored.getJSONObject("matches").length()==0,"undo tombstone prevents stale-device resurrection");
        for(int i=0;i<110;i++){String key=UUID.randomUUID().toString();s.settle(aid,match(key,aid,bid,true,i%4,now+3000+i*1000));}
        JSONObject d=s.read(aid);check(d.getJSONObject("statistics").getInt("games")==110&&d.getJSONObject("statistics").getInt("wins")==110,"long history and wins count once");check(d.getJSONObject("statistics").getInt("best")==110,"winning streak derived in chronological order");check(d.getJSONObject("friendStats").getJSONObject(bid).getInt("intimacy")==1150,"intimacy and once-only friend challenge derived from shared IDs");check(CareerRules.owns(d,"board:jade")&&CareerRules.owns(d,"frame:gold"),"level ten cosmetic rewards actually unlock");s.equip(aid,"board","jade");check(s.read(aid).getJSONObject("outfit").getString("board").equals("jade"),"equipped board skin persisted");check(CareerRules.level(Long.MAX_VALUE)==100&&CareerRules.bondLevel(Long.MAX_VALUE)==20,"player and character levels clamp at caps");check(CareerRules.ACHIEVEMENTS.length>=20,"at least twenty real achievement definitions");
        JSONArray badges=new JSONArray(Arrays.asList("first","win","hundred"));s.badges(aid,badges);check(s.read(aid).getJSONArray("badges").length()==3,"three earned badges can be equipped");rejected=false;try{s.badges(aid,new JSONArray(Arrays.asList("first","win","hundred","win50")));}catch(Exception e){rejected=true;}check(rejected,"fourth badge rejected");s.select(aid);
        ArchiveCloud cloud=new ArchiveCloud(getTargetContext(),s);rejected=false;try{cloud.endpoint("http://insecure.example");}catch(Exception e){rejected=true;}check(rejected,"cleartext cloud endpoint rejected");Method token=ArchiveCloud.class.getDeclaredMethod("token",String.class,String.class);token.setAccessible(true);token.invoke(cloud,aid,"instrumentation-session-only");String cipher=getTargetContext().getSharedPreferences("cloud_endpoint",0).getString("session_"+aid,"");check(!cipher.contains("instrumentation-session-only")&&!cipher.isEmpty(),"session stored encrypted by Android Keystore");Method read=ArchiveCloud.class.getDeclaredMethod("token",String.class);read.setAccessible(true);check(read.invoke(cloud,aid).equals("instrumentation-session-only"),"encrypted session restores across local reads");token.invoke(cloud,aid,"");cloud.close();check(s.read(aid).optBoolean("dirty"),"offline changes remain dirty for retry");
    }
    private void actualBoard()throws Exception{
        activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(()->activity.hasWindowFocus(),"game activity ready");PlayerArchive s=(PlayerArchive)field(activity,"archives");String[] ids=new String[4];for(int i=0;i<4;i++)ids[i]=s.create("座位"+i,false).getString("id");s.select(ids[0]);
        main(()->{try{set(activity,"pendingBindings",ids);Method start=MainActivity.class.getDeclaredMethod("startMatch",String[].class);start.setAccessible(true);start.invoke(activity,(Object)new String[]{"甲","乙","丙","丁"});}catch(Exception e){throw new RuntimeException(e);}});FourChessView board=(FourChessView)field(activity,"board");main(()->{check(board.tryDiplomacy(1,4,0),"real green surrender allowed");check(board.tryDiplomacy(2,4,0),"real blue surrender allowed");check(board.tryDiplomacy(3,4,0),"real gold surrender ends match");});await(()->s.read(ids[3]).getJSONObject("statistics").getInt("games")==1,"all four explicitly bound profiles receive settlement");check(s.read(ids[0]).getJSONObject("statistics").getInt("wins")==1,"actual surviving general wins");for(int i=1;i<4;i++)check(s.read(ids[i]).getJSONObject("statistics").getInt("losses")==1,"defeated seat receives only own loss "+i);check(s.read(ids[0]).getJSONObject("statistics").getInt("captures")==0,"surrender transfers do not count as captures");
        main(()->{board.setLocalPlayer(-1);board.setLocalPlayer(-1);});SystemClock.sleep(120);check(s.read(ids[0]).getJSONObject("statistics").getInt("games")==1,"repeated terminal status never duplicates settlement");main(()->check(board.undoSteps(1),"real post-victory undo still works"));await(()->s.read(ids[3]).getJSONObject("statistics").getInt("games")==0,"undo retracts all bound records and experience");main(()->{try{invoke(activity,"exitToLobby");}catch(Exception e){throw new RuntimeException(e);}});
        FourChessView test=new FourChessView(getTargetContext());test.importState("0,-1,-1,-1,-1|0,J,9,18;1,J,5,8;2,J,9,0;3,J,18,9;0,C,5,10;");check(test.tryNetworkMove(0,5,10,5,8),"actual legal rook captures opposing general");check(test.careerTotals()[0][0]==1,"captured general counts once, eliminated army not counted");check(test.undoSteps(1)&&test.careerTotals()[0][0]==0,"statistics reconstruct exact remaining undo history");
        DraftSkillProbe helper=new DraftSkillProbe();Method fixture=DraftSkillProbe.class.getDeclaredMethod("fixture",int.class,int.class);fixture.setAccessible(true);test.importState((String)fixture.invoke(helper,0,29));check(test.trySkill(0,29,9,9,9,9)&&test.careerTotals()[0][1]==1,"actual successful secret use counted");
        uiPages();
    }
    private void uiPages()throws Exception{boolean portrait=!"landscape".equals(args.getString("orientation","portrait"));main(()->activity.setRequestedOrientation(portrait?1:0));await(()->{View root=(View)field(activity,"screen");return (root.getHeight()>root.getWidth())==portrait;},"career requested orientation ready");main(()->{try{invoke(activity,"openArchive");}catch(Exception e){throw new RuntimeException(e);}});ArchiveCenter page=(ArchiveCenter)field(activity,"archiveCenter");for(String tab:new String[]{"棋士档案","万象荣誉录","棋友录","角色羁绊","棋士衣橱","棋局战绩","棋士生涯","账号与云存档"}){main(()->{try{set(page,"tab",tab);page.render();}catch(Exception e){throw new RuntimeException(e);}});check(page.getWidth()>0&&page.getHeight()>0,"real career page renders "+tab);check(((View)field(activity,"archiveEntry")).getVisibility()==View.GONE,"lobby entry never overlays full profile page "+tab);android.widget.LinearLayout body=(android.widget.LinearLayout)field(page,"body");android.widget.ScrollView scroll=(android.widget.ScrollView)body.getParent();check(body.getWidth()<=page.getWidth()&&scroll.getHeight()>0,"page uses viewport and internal scroll "+tab);main(()->scroll.fullScroll(View.FOCUS_DOWN));check(scroll.getScrollY()>=0,"long page remains reachable "+tab);if(tab.equals("棋士档案")){Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"career-"+(portrait?"portrait":"landscape")+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}}
        main(()->activity.onBackPressed());check(field(activity,"archiveCenter")==null,"system back closes career page and restores game lobby");
    }
    private static class PeerCallback implements NetworkManager.Callback {
        volatile int seat=-1;volatile String state="",status="";volatile JSONObject metadata;
        public void onAssigned(int owner){seat=owner;}public void onState(String s){state=s;}public void onNetworkStatus(String s){status=s;}public void onHostMove(int o,int sx,int sy,int tx,int ty){}
        public void onCareer(JSONObject d){metadata=d;}
    }
    private void tcpCareer()throws Exception{
        PlayerArchive store=new PlayerArchive(getTargetContext());JSONObject a=store.create("房主棋士",false),b=store.create("远端棋士",false);String aid=a.getString("id"),bid=b.getString("id");FourChessView hostBoard=new FourChessView(getTargetContext()),clientBoard=new FourChessView(getTargetContext());NetworkManager[] host={null};Handler handler=new Handler(Looper.getMainLooper());MatchCareer local=new MatchCareer(getTargetContext(),store,message->{});local.begin(new String[]{"",bid,"",""});
        PeerCallback hostCallback=new PeerCallback(){public void onCareerRequest(){handler.post(()->host[0].broadcastCareer());}};
        PeerCallback peerCallback=new PeerCallback(){public void onState(String state){super.onState(state);handler.post(()->clientBoard.importState(state));}public void onCareer(JSONObject d){super.onCareer(d);handler.post(()->{local.network(d,seat,bid);local.observe(clientBoard,true);});}};
        host[0]=new NetworkManager(getTargetContext(),hostCallback,"房主");NetworkManager peer=new NetworkManager(getTargetContext(),peerCallback,"远端");
        try{
            JSONObject card=PlayerArchive.card(a);card.put("session","must-never-be-sent");host[0].setCareerIdentity(card);host[0].host(hostBoard);await(()->hostCallback.status.contains("房间地址"),"actual career TCP host listens");JSONObject other=PlayerArchive.card(b);other.put("owner",0);peer.setCareerIdentity(other);peer.join("127.0.0.1");await(()->peerCallback.seat==1,"career TCP assigns socket seat");await(()->peerCallback.metadata!=null&&bid.equals(peerCallback.metadata.getJSONArray("players").getJSONObject(1).optString("id")),"real TCP public identity exchanged at actual socket seat");JSONObject received=peerCallback.metadata;check(received.getJSONArray("players").getJSONObject(0).getString("id").equals(aid),"peer supplied owner never replaces host identity");check(!received.toString().contains("session")&&!received.toString().contains("must-never"),"LAN metadata never includes private credentials");check(received.getString("fingerprint").equals(MatchCareer.fingerprint(hostBoard.exportState())),"network metadata binds to exact authoritative board snapshot");store.addFriend(bid,received.getJSONArray("players").getJSONObject(0));
            main(()->{check(hostBoard.tryDiplomacy(1,4,0),"network fixture green surrender");check(hostBoard.tryDiplomacy(2,4,0),"network fixture blue surrender");check(hostBoard.tryDiplomacy(3,4,0),"network fixture gold surrender");host[0].broadcast(hostBoard.exportState());});
            await(()->store.read(bid).getJSONObject("statistics").getInt("games")==1,"actual TCP terminal state settles local bound seat");check(store.read(bid).getJSONObject("statistics").getInt("losses")==1,"remote seat result follows authoritative survivor");check(store.read(aid).getJSONObject("statistics").getInt("games")==0,"client settlement never writes another player's archive");check(store.read(bid).getJSONObject("friendStats").getJSONObject(aid).getInt("intimacy")==30,"real LAN participants grant one shared-game intimacy reward");
            main(()->host[0].broadcast(hostBoard.exportState()));SystemClock.sleep(180);check(store.read(bid).getJSONObject("statistics").getInt("games")==1,"repeat TCP snapshot never duplicates local settlement");
        }finally{peer.close();host[0].close();local.close();}SystemClock.sleep(200);
    }
    @Override public void onStart(){Bundle out=new Bundle();try{data();actualBoard();if(!"false".equals(args.getString("network","true")))tcpCareer();log.append("CAREER COMPLETE\n");out.putString("stream",log.toString());finish(Activity.RESULT_OK,out);}catch(Throwable e){out.putString("stream",log+"FAIL "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
}
